## Why This Is Asked
Asks how to extend authorization without touching core, using a plugin/strategy approach to support multiple policy languages at runtime.

## Key Concepts
- Plugin architecture
- Registry and factories
- Strategy-like policy evaluation
- Runtime extensibility and isolation

## Code Example
```javascript
// Minimal TypeScript-like sketch
interface PolicyLanguage {
  evaluate(user: any, resource: any, action: string): boolean;
}
class RBACPolicy implements PolicyLanguage {
  constructor(defs: any) {}
  evaluate(user: any, resource: any, action: string): boolean { /*RBAC logic*/ return true; }
}
class ABACPolicy implements PolicyLanguage {
  constructor(attrs: any) {}
  evaluate(user: any, resource: any, action: string): boolean { /*ABAC logic*/ return true; }
}

class PolicyEngine {
  private registry: any = {};
  register(lang: string, factory: () => PolicyLanguage) { this.registry[lang] = factory; }
  evaluate(user: any, resource: any, action: string, lang?: string): boolean {
    const factory = lang ? this.registry[lang] : this.registry['default'];
    const policy = factory();
    return policy.evaluate(user, resource, action);
  }
}
```

