## Code Example

```typescript
// Interfaces
interface CLIContext { logger: any; config: any; api: any; }
interface Command {
  name: string;
  run(ctx: CLIContext, args: string[]): Promise<void>;
}
type CommandFactory = () => Command;

// Registry skeleton
class CommandRegistry {
  private registry = new Map<string, CommandFactory>();
  async loadPlugin(path: string) { const mod = await import(path); mod.register?.(this); }
  register(name: string, factory: CommandFactory) { this.registry.set(name, factory); }
  get(name: string): Command | undefined { const f = this.registry.get(name); return f ? f() : undefined; }
}
```

